// DMX features of the builder API: combination operators (controls, stereo, n-way and eyelid controls, corrective
// shapes, dominators), "advanced flex" rules, per-vertex stereo balance and vertex cache animations (`vcafile`).
//
// The equivalence tests compare the builder's output byte for byte with the compile of src/combo.dmx /
// src/combo_rules.dmx (generated by make_fixtures.py from the COMBO_* tables there: the grid, the delta states, the
// controls and the rules below are the same numbers) and of vca.qc.
#include "core_helpers.hpp"

#include "anim_helpers.hpp"
#include "flex_helpers.hpp"

using namespace coretest;
using namespace flextest;

namespace {
    // ---- the combo strip (make_fixtures.py: COMBO_VERTS, COMBO_BALANCE, COMBO_SHAPES) ----
    constexpr uint32_t kVertices = 12;
    // what the DMX loader's VectorNormalize makes of (0, 0, 1); the builder keeps the normals as they are
    constexpr float kUnitZ = 0.99999988f;
    constexpr float kBalance[kVertices / 2] = {0.0f, 0.125f, 0.25f, 0.75f, 0.875f, 1.0f}; // per column

    struct ComboShape {
        const char *name;
        std::vector<std::pair<uint32_t, smdl::Vec3>> deltas;
    };

    const std::vector<ComboShape> &ComboShapes() {
        static const std::vector<ComboShape> shapes = {
            {"browDown", {{1, {0, 0, -0.5f}}, {3, {0, 0, -0.5f}}, {5, {0, 0, -0.5f}}, {7, {0, 0, -0.5f}},
                          {9, {0, 0, -0.5f}}, {11, {0, 0, -0.5f}}}},
            {"browUp", {{1, {0, 0, 1}}, {3, {0, 0, 1}}, {5, {0, 0, 1}}, {7, {0, 0, 1}}, {9, {0, 0, 1}}, {11, {0, 0, 1}}}},
            {"smile", {{0, {-0.5f, 0, 0.25f}}, {1, {-0.5f, 0, 0.25f}}, {10, {0.5f, 0, 0.25f}}, {11, {0.5f, 0, 0.25f}}}},
            {"jaw", {{0, {0, -1, 0}}, {2, {0, -1, 0}}, {4, {0, -1, 0}}, {6, {0, -1, 0}}, {8, {0, -1, 0}}, {10, {0, -1, 0}}}},
            {"oo", {{4, {0, 0, 0.5f}}, {5, {0, 0, 0.5f}}, {6, {0, 0, 0.5f}}, {7, {0, 0, 0.5f}}}},
            {"ee", {{4, {0.25f, 0, 0}}, {6, {-0.25f, 0, 0}}}},
            {"aa", {{5, {0, -0.25f, 0}}, {7, {0, -0.25f, 0}}}},
            {"lowLid", {{2, {0, 0, 0.25f}}, {4, {0, 0, 0.25f}}}},
            {"upLid", {{3, {0, 0, -0.25f}}, {5, {0, 0, -0.25f}}}},
            {"smile_jaw", {{0, {0.25f, 0, 0}}, {10, {-0.25f, 0, 0}}}},
            {"browUp_smile", {{1, {0, 0.25f, 0.25f}}, {11, {0, 0.25f, 0.25f}}}},
        };
        return shapes;
    }

    std::vector<float> ComboBalance() {
        std::vector<float> balance;
        for (uint32_t i = 0; i < kVertices; ++i)
            balance.push_back(kBalance[i / 2]);
        return balance;
    }

    // The strip as a mesh of the model (the model gets its bone), without shapes or balance. The triangles are the
    // polygons of the DMX face set (make_fixtures.py: combo_triangles): a strip, for which the unified vertices come
    // out in the vertex order in the SMD loader's order (by last use) and in the DMX loader's (by first use).
    smdl::Mesh AddComboGrid(smdl::Model &model, const char *meshName = "src/combo.dmx") {
        // the DMX loader's quaternion (0, 0, 0, 1) becomes the euler angles (0, -0, 0)
        const smdl::BoneId root = model.addBoneEuler("root", smdl::NoBone, {0, 0, 0}, {0.0f, -0.0f, 0.0f});
        smdl::BodyGroup group = model.addBodyGroup("combo");
        smdl::Mesh mesh = group.createMesh(meshName);
        smdl::Geometry geometry = mesh.geometry();

        const smdl::MaterialId material = geometry.addMaterial("combo_mat");
        std::vector<smdl::Vec3> positions, normals;
        std::vector<smdl::Vec2> uvs;
        for (uint32_t i = 0; i < kVertices; ++i) {
            positions.push_back({2.0f * static_cast<float>(i / 2), 2.0f * static_cast<float>(i % 2), 0.0f});
            normals.push_back({0, 0, kUnitZ});
            uvs.push_back({0.125f * static_cast<float>(i / 2), 0.5f * static_cast<float>(i % 2)});
        }
        std::vector<uint32_t> indices;
        for (uint32_t k = 0; k + 2 < kVertices; ++k) {
            const std::array<uint32_t, 3> polygon = k % 2 == 0 ? std::array<uint32_t, 3>{k, k + 2, k + 1}
                                                               : std::array<uint32_t, 3>{k, k + 1, k + 2};
            indices.insert(indices.end(), polygon.begin(), polygon.end());
        }
        geometry.setRelativeMaterials(true); // DMX materials
        geometry.setPositions(positions);
        geometry.setNormals(normals);
        geometry.setUVs(0, uvs);
        geometry.setWeights(1, std::vector<smdl::BoneId>(positions.size(), root), std::vector<float>(positions.size(), 1.0f));
        geometry.setTriangles(indices, std::vector<smdl::MaterialId>(indices.size() / 3, material));
        return mesh;
    }

    void AddComboShapes(smdl::Geometry geometry) {
        for (const ComboShape &shape: ComboShapes()) {
            std::vector<uint32_t> vertices;
            std::vector<smdl::Vec3> deltas;
            for (const auto &[vertex, delta]: shape.deltas) {
                vertices.push_back(vertex);
                deltas.push_back(delta);
            }
            geometry.addShape(shape.name, vertices, deltas);
        }
    }

    // The controls of COMBO_CONTROLS; `ranges`: also the flexMin/flexMax of the DMX (only "advanced flex" uses them)
    void AddComboControls(const smdl::Mesh &mesh, bool ranges) {
        const smdl::CombinationControlId brow = mesh.addCombinationControl("brow", {"browDown", "browUp"});
        const smdl::CombinationControlId smile = mesh.addCombinationControl("smile", {"smile"}, true);
        const smdl::CombinationControlId jaw = mesh.addCombinationControl("jaw", {"jaw"});
        const smdl::CombinationControlId vowel = mesh.addCombinationControl("vowel", {"oo", "ee", "aa"});
        const smdl::CombinationControlId lid = mesh.addCombinationControl("lid", {"lowLid", "upLid"});
        mesh.setCombinationControlEyelid(lid);
        if (ranges) {
            mesh.setCombinationControlRange(brow, -1.0f, 1.0f);
            mesh.setCombinationControlRange(smile, 0.0f, 1.0f);
            mesh.setCombinationControlRange(jaw, 0.0f, 1.0f);
            mesh.setCombinationControlRange(vowel, -1.0f, 1.0f);
            mesh.setCombinationControlRange(lid, -1.0f, 1.0f);
        }
    }

    smdl::Model ComboModel(const char *name) {
        smdl::Model model(name);
        BasicGlobals(model, "flesh");
        NoSequences(model);
        return model;
    }

    // The model of combo.qc through the C++ API
    smdl::Model BuildCombo(bool balance = true) {
        smdl::Model model = ComboModel("api/combo");
        smdl::Mesh mesh = AddComboGrid(model);
        AddComboShapes(mesh.geometry());
        if (balance)
            mesh.geometry().setBalance(ComboBalance());
        AddComboControls(mesh, false);
        mesh.addCombinationDominator({"jaw"}, {"smile"});
        return model;
    }

    // The model of combo_rules.qc
    smdl::Model BuildComboRules() {
        smdl::Model model = ComboModel("api/combo_rules");
        smdl::Mesh mesh = AddComboGrid(model, "src/combo_rules.dmx");
        AddComboShapes(mesh.geometry());
        mesh.geometry().setBalance(ComboBalance());
        AddComboControls(mesh, true);
        mesh.addCombinationDominator({"jaw"}, {"smile"});
        mesh.addCombinationLocalVar("amount");
        mesh.addCombinationExpression("amount", "smile * 0.5 + 0.25");
        mesh.addCombinationExpression("smileR", "smile");
        mesh.addCombinationExpression("smileL", "smile * 0.5 + %amount * 0.5");
        mesh.addCombinationPassThrough("jaw");
        mesh.addCombinationExpression("browUp", "max(brow, 0)");
        mesh.addCombinationExpression("browDown", "max(-brow, 0)");
        return model;
    }

    smdl_status StatusOf(const std::function<void()> &call) { return CaptureError(call).status(); }
}

// ---------------------------------------------------------------------------------------------------------------
// Equivalence with the DMX compile
// ---------------------------------------------------------------------------------------------------------------

// stereo, n-way and eyelid controls, corrective shapes, a dominator, balance
SMDL_TEST(combination_equiv_dmx) {
    smdl::Model model = BuildCombo();
    RequireSameAsQc(model, "combo.qc");
}

// "advanced flex": controllers with ranges, expression, pass-through and local variable rules
SMDL_TEST(combination_equiv_dmx_flex_rules) {
    smdl::Model model = BuildComboRules();
    RequireSameAsQc(model, "combo_rules.qc");
}

// The balance reaches the MDL: the same model without it is not the DMX compile
SMDL_TEST(combination_balance_is_stored) {
    smdl::Model withBalance = BuildCombo(true);
    smdl::Model withoutBalance = BuildCombo(false);
    withBalance.setQcPath(QcPathEntry(FixturePath("combo.qc")));
    withoutBalance.setQcPath(QcPathEntry(FixturePath("combo.qc")));
    const Outputs expected = ResultFiles(withBalance.compile());
    const Outputs actual = ResultFiles(withoutBalance.compile());
    Require(expected.at("models/api/combo.mdl") != actual.at("models/api/combo.mdl"),
            "the per-vertex balance changes the MDL");
}

// The C API drives the same compile
SMDL_TEST(combination_c_api) {
    smdl::Model model = ComboModel("api/combo");
    smdl::Mesh mesh = AddComboGrid(model);
    AddComboShapes(mesh.geometry());
    const std::vector<float> balance = ComboBalance();
    Require(smdl_geometry_set_balance(mesh.geometry().handle(), balance.data(), balance.size(), 0) == SMDL_OK,
            "smdl_geometry_set_balance");

    smdl_mesh *handle = mesh.handle();
    uint32_t id = SMDL_NO_ID;
    const char *const brow[] = {"browDown", "browUp"};
    const char *const smile[] = {"smile"};
    const char *const jaw[] = {"jaw"};
    const char *const vowel[] = {"oo", "ee", "aa"};
    const char *const lid[] = {"lowLid", "upLid"};
    Require(smdl_mesh_add_combination_control(handle, "brow", brow, 2, 0, &id) == SMDL_OK && id == 0, "brow");
    Require(smdl_mesh_add_combination_control(handle, "smile", smile, 1, 1, &id) == SMDL_OK && id == 1, "smile");
    Require(smdl_mesh_add_combination_control(handle, "jaw", jaw, 1, 0, &id) == SMDL_OK && id == 2, "jaw");
    Require(smdl_mesh_add_combination_control(handle, "vowel", vowel, 3, 0, &id) == SMDL_OK && id == 3, "vowel");
    Require(smdl_mesh_add_combination_control(handle, "lid", lid, 2, 0, &id) == SMDL_OK && id == 4, "lid");
    Require(smdl_mesh_set_combination_control_eyelid(handle, id, nullptr) == SMDL_OK, "eyelid");
    Require(smdl_mesh_add_combination_dominator(handle, jaw, 1, smile, 1) == SMDL_OK, "dominator");
    RequireSameAsQc(model, "combo.qc");

    // and the flex rules
    smdl::Model rulesModel = ComboModel("api/combo_rules");
    smdl::Mesh rulesMesh = AddComboGrid(rulesModel, "src/combo_rules.dmx");
    AddComboShapes(rulesMesh.geometry());
    rulesMesh.geometry().setBalance(balance);
    AddComboControls(rulesMesh, true);
    rulesMesh.addCombinationDominator({"jaw"}, {"smile"});
    handle = rulesMesh.handle();
    Require(smdl_mesh_add_combination_local_var(handle, "amount") == SMDL_OK, "local var");
    Require(smdl_mesh_add_combination_expression(handle, "amount", "smile * 0.5 + 0.25") == SMDL_OK, "amount");
    Require(smdl_mesh_add_combination_expression(handle, "smileR", "smile") == SMDL_OK, "smileR");
    Require(smdl_mesh_add_combination_expression(handle, "smileL", "smile * 0.5 + %amount * 0.5") == SMDL_OK,
            "smileL");
    Require(smdl_mesh_add_combination_pass_through(handle, "jaw") == SMDL_OK, "pass-through");
    Require(smdl_mesh_add_combination_expression(handle, "browUp", "max(brow, 0)") == SMDL_OK, "browUp");
    Require(smdl_mesh_add_combination_expression(handle, "browDown", "max(-brow, 0)") == SMDL_OK, "browDown");
    RequireSameAsQc(rulesModel, "combo_rules.qc");
}

// ---------------------------------------------------------------------------------------------------------------
// Vertex cache animation
// ---------------------------------------------------------------------------------------------------------------

namespace {
    // face.smd with the shapes of face.vta (frames 1..K = shapes 0..K-1), the vca.qc model
    smdl::Model BuildVca(smdl::Mesh *outMesh = nullptr) {
        smdl::Model model("api/vca");
        BasicGlobals(model, "flesh");
        smdl::BodyGroup group = model.addBodyGroup("face");
        const SmdFile smd = ReadSmd(FixturePath("src/face.smd"));
        smdl::Mesh face = AddMesh(model, group, "src/face.smd", "src/face.smd", VertexMode::Corners);
        AddVtaShapes(face.geometry(), smd, VertexMode::Corners, ReadVta(FixturePath("src/face.vta")));
        smdl::Animation idle = animtest::AddAnimationFromSmd(model, "a_idle", "src/anims/face_idle.smd", 30.0f);
        idle.setLoop();
        model.createSequence("idle").addAnimation(idle);
        if (outMesh)
            *outMesh = face;
        return model;
    }
}

SMDL_TEST(vertex_cache_animation_equiv_vcafile) {
    smdl::Mesh face{nullptr, nullptr};
    smdl::Model model = BuildVca(&face);
    std::vector<smdl::ShapeId> frames;
    for (uint32_t shape = 0; shape < face.geometry().shapeCount(); ++shape)
        frames.push_back(shape);
    Require(frames.size() == 3, "face.vta has three frames after frame 0");
    // the Nway controller is named after the VTA file
    face.addVertexCacheAnimation("face", frames);
    RequireSameAsQc(model, "vca.qc");
}

SMDL_TEST(vertex_cache_animation_c_api) {
    smdl::Mesh face{nullptr, nullptr};
    smdl::Model model = BuildVca(&face);
    const uint32_t frames[] = {0, 1, 2};
    Require(smdl_mesh_add_vertex_cache_animation(face.handle(), "face", frames, 3, 0) == SMDL_OK,
            "smdl_mesh_add_vertex_cache_animation");
    RequireSameAsQc(model, "vca.qc");
}

// ---------------------------------------------------------------------------------------------------------------
// Call-time validation and compile errors
// ---------------------------------------------------------------------------------------------------------------

SMDL_TEST(combination_validation) {
    smdl::Model model = ComboModel("api/combo");
    smdl::Mesh mesh = AddComboGrid(model);
    mesh.addCombinationControl("brow", {"browDown", "browUp"});

    Require(StatusOf([&] { mesh.addCombinationControl("BROW", {"x"}); }) == SMDL_ERROR_DUPLICATE_NAME,
            "control names are unique");
    Require(StatusOf([&] { mesh.addCombinationControl("other", {"browup"}); }) == SMDL_ERROR_DUPLICATE_NAME,
            "a raw control belongs to one control (case-insensitive)");
    Require(StatusOf([&] { mesh.addCombinationControl("twice", {"a", "A"}); }) == SMDL_ERROR_DUPLICATE_NAME,
            "a raw control is listed once");
    Require(StatusOf([&] { mesh.addCombinationControl("none", std::span<const std::string_view>()); }) ==
                    SMDL_ERROR_INVALID_ARGUMENT,
            "a control has raw controls");
    Require(StatusOf([&] { mesh.addCombinationControl("", {"x"}); }) == SMDL_ERROR_INVALID_ARGUMENT, "control name");
    Require(StatusOf([&] { mesh.addCombinationControl("y", {""}); }) == SMDL_ERROR_INVALID_ARGUMENT, "raw control name");
    Require(StatusOf([&] { mesh.addCombinationControl(std::string(125, 'n'), {"x"}); }) == SMDL_ERROR_LIMIT,
            "the prefixed controller names must fit");

    mesh.setCombinationControlEyelid(0); // two raw controls make an eyelid control
    const smdl::CombinationControlId single = mesh.addCombinationControl("single", {"one"});
    Require(StatusOf([&] { mesh.setCombinationControlEyelid(single); }) == SMDL_ERROR_INVALID_ARGUMENT,
            "an eyelid control has two raw controls");
    Require(StatusOf([&] { mesh.setCombinationControlEyelid(9); }) == SMDL_ERROR_OUT_OF_RANGE, "control index");
    Require(StatusOf([&] { mesh.setCombinationControlRange(9, 0, 1); }) == SMDL_ERROR_OUT_OF_RANGE, "range: control index");
    Require(StatusOf([&] { mesh.setCombinationControlRange(0, 0, std::nanf("")); }) == SMDL_ERROR_INVALID_ARGUMENT,
            "range is finite");

    Require(StatusOf([&] { mesh.addCombinationDominator({}, {"a"}); }) == SMDL_ERROR_INVALID_ARGUMENT,
            "dominators needed");
    Require(StatusOf([&] { mesh.addCombinationDominator({"a"}, {}); }) == SMDL_ERROR_INVALID_ARGUMENT,
            "suppressed needed");

    // flex rules: syntax is checked when the rule is added, names by the compile
    Require(StatusOf([&] { mesh.addCombinationExpression("x", "1 +"); }) == SMDL_ERROR_SYNTAX, "malformed expression");
    Require(StatusOf([&] { mesh.addCombinationExpression("x", ""); }) == SMDL_ERROR_SYNTAX, "empty expression");
    Require(StatusOf([&] { mesh.addCombinationExpression("x", "1 ; 2"); }) == SMDL_ERROR_SYNTAX, "comment in expression");
    mesh.addCombinationExpression("x", "unknown_controller * 2");
    Require(StatusOf([&] { mesh.addCombinationExpression("X", "1"); }) == SMDL_ERROR_DUPLICATE_NAME,
            "a flex has one rule");
    Require(StatusOf([&] { mesh.addCombinationPassThrough("x"); }) == SMDL_ERROR_DUPLICATE_NAME, "pass-through duplicate");
    mesh.addCombinationLocalVar("v");
    mesh.addCombinationExpression("v", "1"); // a local variable gets its rule from an expression
    Require(StatusOf([&] { mesh.addCombinationLocalVar("v"); }) == SMDL_ERROR_DUPLICATE_NAME, "local variable duplicate");

    // the unknown controller is a compile error that names the rule
    const smdl::Error error = CaptureError([&] { model.compile(); });
    Require(Contains(error.what(), "unknown_controller") || Contains(error.object(), "combination"),
            "the compile names the problem: " + std::string(error.what()));
}

SMDL_TEST(combination_compile_errors) {
    // a domination rule must name raw controls
    smdl::Model model = ComboModel("api/combo");
    smdl::Mesh mesh = AddComboGrid(model);
    AddComboShapes(mesh.geometry());
    mesh.addCombinationControl("brow", {"browDown", "browUp"});
    mesh.addCombinationDominator({"nothing"}, {"browUp"});
    smdl::Error error = CaptureError([&] { model.compile(); });
    Require(Contains(error.object(), "combination operator of mesh 'src/combo.dmx'"),
            "names the combination operator: " + error.object());
    Require(Contains(error.what(), "nothing"), "names the raw control: " + std::string(error.what()));

    // balance: one value per vertex, in 0..1
    smdl::Model other = ComboModel("api/combo");
    smdl::Mesh otherMesh = AddComboGrid(other);
    smdl::Geometry geometry = otherMesh.geometry();
    Require(StatusOf([&] { geometry.setBalance(std::vector<float>(3, 0.5f)); }) == SMDL_ERROR_INVALID_ARGUMENT,
            "balance count");
    std::vector<float> balance = ComboBalance();
    balance[5] = 1.5f;
    Require(StatusOf([&] { geometry.setBalance(balance); }) == SMDL_ERROR_INVALID_ARGUMENT, "balance range");
    balance[5] = std::nanf("");
    Require(StatusOf([&] { geometry.setBalance(balance); }) == SMDL_ERROR_INVALID_ARGUMENT, "balance finite");
    smdl::Model empty = ComboModel("api/combo");
    const smdl::BodyGroup group = empty.addBodyGroup("g");
    smdl::Geometry noPositions = group.createMesh("m").geometry();
    Require(StatusOf([&] { noPositions.setBalance(std::vector<float>(1, 0.5f)); }) == SMDL_ERROR_INVALID_ARGUMENT,
            "balance needs the positions");
}

SMDL_TEST(vertex_cache_animation_validation) {
    smdl::Mesh face{nullptr, nullptr};
    smdl::Model model = BuildVca(&face);
    Require(StatusOf([&] { face.addVertexCacheAnimation("face", std::span<const smdl::ShapeId>()); }) ==
                    SMDL_ERROR_INVALID_ARGUMENT,
            "frames needed");
    const smdl::ShapeId missing[] = {0, 7};
    Require(StatusOf([&] { face.addVertexCacheAnimation("face", missing); }) == SMDL_ERROR_OUT_OF_RANGE, "shape range");
    const smdl::ShapeId base[] = {smdl::NoId};
    Require(StatusOf([&] { face.addVertexCacheAnimation("face", base); }) == SMDL_ERROR_OUT_OF_RANGE,
            "the base pose is frame 0 already");
    Require(StatusOf([&] { face.addVertexCacheAnimation("", std::span<const smdl::ShapeId>(base, 0)); }) ==
                    SMDL_ERROR_INVALID_ARGUMENT,
            "name");

    const smdl::ShapeId frames[] = {0, 1};
    face.addVertexCacheAnimation("face", frames);
    Require(StatusOf([&] { face.addVertexCacheAnimation("again", frames); }) == SMDL_ERROR_INVALID_ARGUMENT,
            "one vertex cache animation per mesh");
    Require(StatusOf([&] { face.addCombinationControl("x", {"y"}); }) == SMDL_ERROR_INVALID_ARGUMENT,
            "no combination operator next to a vertex cache animation");

    // a flex before it is rejected like the QC rejects it
    smdl::Mesh other{nullptr, nullptr};
    smdl::Model otherModel = BuildVca(&other);
    other.addFlex("blink", 0);
    Require(StatusOf([&] { other.addVertexCacheAnimation("face", frames); }) == SMDL_ERROR_INVALID_ARGUMENT,
            "vertex cache animation must be the only flex option");

    // flexes of an earlier mesh: "Flexes already defined" at compile time
    smdl::Model two("api/vca2");
    BasicGlobals(two, "flesh");
    const SmdFile smd = ReadSmd(FixturePath("src/face.smd"));
    smdl::BodyGroup first = two.addBodyGroup("first");
    smdl::Mesh firstMesh = AddMesh(two, first, "first", "src/face.smd", VertexMode::Corners);
    AddVtaShapes(firstMesh.geometry(), smd, VertexMode::Corners, ReadVta(FixturePath("src/face.vta")));
    firstMesh.addFlex("blink", 0);
    smdl::BodyGroup secondGroup = two.addBodyGroup("second");
    smdl::Mesh secondMesh = AddMesh(two, secondGroup, "second", "src/face.smd", VertexMode::Corners, false);
    AddVtaShapes(secondMesh.geometry(), smd, VertexMode::Corners, ReadVta(FixturePath("src/face.vta")));
    secondMesh.addVertexCacheAnimation("second", frames);
    NoSequences(two);
    const smdl::Error error = CaptureError([&] { two.compile(); });
    Require(Contains(error.what(), "Flexes already defined"), "compile error: " + std::string(error.what()));
}
